def backup(path: Path) -> None:
    if not path.exists():
        return
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_path = path.with_name(path.name + f".before_smalta_alignment_{stamp}.bak")
    n = 1
    while backup_path.exists():
        backup_path = path.with_name(path.name + f".before_smalta_alignment_{stamp}_{n}.bak")
        n += 1
    shutil.copy2(path, backup_path)
    print(f"Резервная копия: {backup_path.name}")


def locate_root() -> Path:
    here = Path(__file__).resolve().parent
    for folder in (here, *here.parents):
        if (folder / "main.py").is_file() and (folder / "config.py").is_file() and (folder / "controls").is_dir():
            return folder
    raise FileNotFoundError("Положи установщик рядом с main.py, config.py и папками controls/ и devices/.")


def write_payloads(root: Path) -> None:
    for relative, encoded in PAYLOADS.items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        data = base64.b64decode(encoded)
        if target.exists() and target.read_bytes() == data:
            print(f"Без изменений: {relative}")
            continue
        backup(target)
        target.write_bytes(data)
        print(f"Установлено: {relative}")


def replace_method(source: str, method_name: str, replacement: str) -> tuple[str, bool]:
    pattern = re.compile(rf"(?ms)^    def {re.escape(method_name)}\(.*?(?=^    def [A-Za-z_]\w*\(|^class [A-Za-z_]\w*|\Z)")
    match = pattern.search(source)
    if not match:
        return source, False
    current = match.group(0).rstrip()
    wanted = replacement.rstrip()
    if current == wanted:
        return source, True
    changed, count = pattern.subn(lambda _match: wanted + "\n\n", source, count=1)
    return changed, bool(count)


def mirror_frozen_assets(root: Path) -> None:
    """Mirror updated panel art and control sprites into a one-folder PyInstaller layout."""
    source_assets = root / "assets" / "Smalta"
    frozen_assets = root / "_internal" / "assets" / "Smalta"
    if not frozen_assets.parent.parent.exists():
        return
    for relative in (
        Path("Backgrounds") / "LO01P.png",
        Path("Controls") / "lever_tall_red.png",
        Path("Controls") / "lever_tall_white.png",
        Path("Controls") / "lever_small_toggle.png",
        Path("Controls") / "lever_ball_red.png",
        Path("Controls") / "lever_ivory.png",
        Path("Controls") / "button_on.png",
        Path("Controls") / "button_off.png",
    ):
        src = source_assets / relative
        dst = frozen_assets / relative
        if src.exists():
            dst.parent.mkdir(parents=True, exist_ok=True)
            if not dst.exists() or dst.read_bytes() != src.read_bytes():
                backup(dst)
                shutil.copy2(src, dst)
                print(f"Обновлён ресурс PyInstaller: _internal/assets/Smalta/{relative.as_posix()}")


def patch_device_base(root: Path) -> None:
    path = root / "devices" / "device_base.py"
    if not path.exists():
        print("ПРЕДУПРЕЖДЕНИЕ: devices/device_base.py не найден")
        return
    original = source = path.read_text(encoding="utf-8")

    if "self.use_native_coordinates" not in source:
        marker = "        self.page_backgrounds: Dict[Any, pygame.Surface] = {}"
        if marker in source:
            source = source.replace(marker, marker + "\n        # Smalta stores element positions in the original image's pixel grid.\n        self.use_native_coordinates = False", 1)
        else:
            print("ПРЕДУПРЕЖДЕНИЕ: не найдено поле page_backgrounds в DeviceBase")

    set_background = '''    def set_background(self, page_key: Any, image_path: str):
        raw = pygame.image.load(str(image_path))
        if pygame.display.get_surface() is not None:
            raw = raw.convert_alpha() if getattr(self, "use_native_coordinates", False) else raw.convert()

        # Native mode stores the unscaled background. All controls are drawn
        # on its pixel grid, then the complete image is scaled as one layer.
        if getattr(self, "use_native_coordinates", False):
            self.page_backgrounds[page_key] = raw
            return

        # Legacy canvas mode for other devices (e.g. RLS) remains unchanged.
        orig_w, orig_h = raw.get_size()
        scale = min(CANVAS_WIDTH / orig_w, CANVAS_HEIGHT / orig_h)
        scaled_w = int(round(orig_w * scale))
        scaled_h = int(round(orig_h * scale))
        scaled_img = pygame.transform.smoothscale(raw, (scaled_w, scaled_h))
        canvas_bg = pygame.Surface((CANVAS_WIDTH, CANVAS_HEIGHT))
        canvas_bg.fill((20, 24, 28))
        offset_x = (CANVAS_WIDTH - scaled_w) // 2
        offset_y = (CANVAS_HEIGHT - scaled_h) // 2
        canvas_bg.blit(scaled_img, (offset_x, offset_y))
        self.page_backgrounds[page_key] = canvas_bg
'''
    source, ok = replace_method(source, "set_background", set_background)
    if not ok:
        print("ПРЕДУПРЕЖДЕНИЕ: не удалось обновить DeviceBase.set_background")

    handle_event = '''    def handle_event(self, event: pygame.event.Event) -> bool:
        if not getattr(self, "use_native_coordinates", False):
            for el in reversed(self.get_elements_for_page(self.current_page_key)):
                if el.handle_event(event):
                    return True
            return False

        bg = self.page_backgrounds.get(self.current_page_key)
        if bg is None:
            return False
        source_w, source_h = bg.get_size()
        scale = min(CANVAS_WIDTH / source_w, CANVAS_HEIGHT / source_h)
        target_w = int(round(source_w * scale))
        target_h = int(round(source_h * scale))
        offset_x = (CANVAS_WIDTH - target_w) // 2
        offset_y = (CANVAS_HEIGHT - target_h) // 2

        if hasattr(event, "pos"):
            x, y = event.pos
            inside = (offset_x <= x < offset_x + target_w and offset_y <= y < offset_y + target_h)
            # Ignore clicks on the dark margin. Still pass mouse-up outside the
            # picture through so a pressed BigButton can release correctly.
            if not inside and event.type == pygame.MOUSEBUTTONDOWN:
                return False
            native_pos = (int((x - offset_x) / scale), int((y - offset_y) / scale))
            event = pygame.event.Event(event.type, {**event.dict, "pos": native_pos})

        for el in reversed(self.get_elements_for_page(self.current_page_key)):
            if el.handle_event(event):
                return True
        return False
'''
    source, ok = replace_method(source, "handle_event", handle_event)
    if not ok:
        print("ПРЕДУПРЕЖДЕНИЕ: не удалось обновить DeviceBase.handle_event")

    native_rect_method = '''    def native_rect_to_canvas(self, rect: pygame.Rect) -> pygame.Rect:
        """Map a rect from original-image pixels to the visible simulation canvas."""
        if not getattr(self, "use_native_coordinates", False):
            return rect.copy()
        bg = self.page_backgrounds.get(self.current_page_key)
        if bg is None:
            return rect.copy()
        source_w, source_h = bg.get_size()
        scale = min(CANVAS_WIDTH / source_w, CANVAS_HEIGHT / source_h)
        target_w = int(round(source_w * scale))
        target_h = int(round(source_h * scale))
        offset_x = (CANVAS_WIDTH - target_w) // 2
        offset_y = (CANVAS_HEIGHT - target_h) // 2
        return pygame.Rect(
            round(rect.x * scale + offset_x),
            round(rect.y * scale + offset_y),
            max(1, round(rect.width * scale)),
            max(1, round(rect.height * scale)),
        )
'''
    if re.search(r"(?m)^    def native_rect_to_canvas\(", source):
        source, ok = replace_method(source, "native_rect_to_canvas", native_rect_method)
        if not ok:
            print("ПРЕДУПРЕЖДЕНИЕ: не удалось обновить native_rect_to_canvas")
    else:
        marker = re.search(r"(?m)^    def draw\(self, surface: pygame\.Surface\):", source)
        if marker:
            source = source[:marker.start()] + native_rect_method + "\n\n" + source[marker.start():]
        else:
            print("ПРЕДУПРЕЖДЕНИЕ: не удалось вставить native_rect_to_canvas")

    draw = '''    def draw(self, surface: pygame.Surface):
        bg = self.page_backgrounds.get(self.current_page_key)
        if bg is None:
            surface.fill((40, 45, 50))
            return

        if not getattr(self, "use_native_coordinates", False):
            surface.blit(bg, (0, 0))
            for el in self.get_elements_for_page(self.current_page_key):
                el.draw(surface)
            return

        source_w, source_h = bg.get_size()
        scale = min(CANVAS_WIDTH / source_w, CANVAS_HEIGHT / source_h)
        target_w = int(round(source_w * scale))
        target_h = int(round(source_h * scale))
        offset_x = (CANVAS_WIDTH - target_w) // 2
        offset_y = (CANVAS_HEIGHT - target_h) // 2

        # Build the composite in native pixels first: background, sprites, and
        # hit rectangles all share a single coordinate system.
        native = pygame.Surface((source_w, source_h), pygame.SRCALPHA, 32)
        native.fill((18, 24, 29, 255))
        native.blit(bg, (0, 0))
        for el in self.get_elements_for_page(self.current_page_key):
            el.draw(native)

        scaled = pygame.transform.smoothscale(native, (target_w, target_h))
        surface.fill((18, 24, 29))
        surface.blit(scaled, (offset_x, offset_y))
'''
    source, ok = replace_method(source, "draw", draw)
    if not ok:
        print("ПРЕДУПРЕЖДЕНИЕ: не удалось обновить DeviceBase.draw")

    if source != original:
        backup(path)
        path.write_text(source, encoding="utf-8")
        print("Исправлена система координат в DeviceBase (только для Smalta)")
    else:
        print("DeviceBase уже обновлён")


def patch_smalta_coordinates(root: Path) -> None:
    path = root / "devices" / "smalta.py"
    if not path.exists():
        print("ПРЕДУПРЕЖДЕНИЕ: devices/smalta.py не найден")
        return
    original = source = path.read_text(encoding="utf-8")
    changed = 0
    missing = []
    for name, (top, left) in COORDINATES.items():
        pattern = re.compile(
            r'((?:Thumbler|BigButton|Lightbox|GaugeArrow|Lamp|RotateStepWheel)\(\s*["\']'
            + re.escape(name) + r'["\']\s*,\s*)(-?\d+)(\s*,\s*)(-?\d+)'
        )
        def repl(match, top=top, left=left):
            return match.group(1) + str(top) + match.group(3) + str(left)
        source, n = pattern.subn(repl, source, count=1)
        if n:
            changed += 1
        else:
            missing.append(name)

    if "device.use_native_coordinates = True" not in source:
        pattern = re.compile(r"(?m)^([ \t]*device = DeviceBase\([^\n]*\))")
        source, n = pattern.subn(r"\1\n    device.use_native_coordinates = True", source, count=1)
        if not n:
            print("ПРЕДУПРЕЖДЕНИЕ: не удалось включить native-coordinate режим для Smalta")

    if source != original:
        backup(path)
        path.write_text(source, encoding="utf-8")
        print(f"Координаты приведены к исходным изображениям: {changed}/{len(COORDINATES)} элементов")
    else:
        print("Координаты Smalta уже совпадают с исправленной схемой")
    if missing:
        print(f"ПРЕДУПРЕЖДЕНИЕ: не найдены вызовы {len(missing)} элементов (например: {', '.join(missing[:4])})")


def patch_lightbox(root: Path) -> None:
    path = root / "controls" / "lightbox.py"
    if not path.exists():
        print("ПРЕДУПРЕЖДЕНИЕ: controls/lightbox.py не найден")
        return
    original = source = path.read_text(encoding="utf-8")
    method = '''    def draw(self, surface: pygame.Surface):
        # The LO01-P image already contains the printed status-label text. In
        # native-art mode only tint the physical plaque; don't print the same
        # label a second time on top of itself.
        if self.device and getattr(self.device, "use_native_coordinates", False):
            box_surf = pygame.Surface((self.width, self.height), pygame.SRCALPHA, 32)
            r, g, b = self.bg_color
            alpha = 115 if self.value == 1 else 22
            pygame.draw.rect(box_surf, (r, g, b, alpha), (0, 0, self.width, self.height), border_radius=3)
            if self.value == 1:
                border = (min(255, r + 45), min(255, g + 45), min(255, b + 45), 210)
                pygame.draw.rect(box_surf, border, (0, 0, self.width, self.height), width=2, border_radius=3)
            surface.blit(box_surf, (self.pos_left, self.pos_top))
            return

        # Legacy devices keep the original label and text rendering behavior.
        box_surf = pygame.Surface((self.width, self.height), pygame.SRCALPHA)
        alpha = 255 if self.value == 1 else 75
        r, g, b = self.bg_color
        pygame.draw.rect(box_surf, (r, g, b, alpha), (0, 0, self.width, self.height), border_radius=3)
        if self.value == 1:
            border_color = (min(255, r + 50), min(255, g + 50), min(255, b + 50), 255)
            pygame.draw.rect(box_surf, border_color, (0, 0, self.width, self.height), width=1, border_radius=3)
        else:
            pygame.draw.rect(box_surf, (40, 50, 45, 120), (0, 0, self.width, self.height), width=1, border_radius=3)

        lines = [line.strip() for line in self.text.split("\\n") if line.strip()]
        if not lines:
            surface.blit(box_surf, (self.pos_left, self.pos_top))
            return
        font_sz = 8 if len(lines) > 1 else 9
        font = self._fonts.get(font_sz) or pygame.font.SysFont("Arial", font_sz, bold=True)
        max_w = max(font.render(line, True, (0, 0, 0)).get_width() for line in lines)
        if max_w > self.width - 6:
            font = self._fonts.get(7) or pygame.font.SysFont("Arial", 7, bold=True)
        text_color = (10, 25, 10) if self.value == 1 else (170, 185, 175)
        rendered = [font.render(line, True, text_color) for line in lines]
        total_h = sum(item.get_height() for item in rendered) + (len(rendered) - 1)
        y = max(1, (self.height - total_h) // 2)
        for item in rendered:
            box_surf.blit(item, ((self.width - item.get_width()) // 2, y))
            y += item.get_height() + 1
        surface.blit(box_surf, (self.pos_left, self.pos_top))
'''
    source, ok = replace_method(source, "draw", method)
    if not ok:
        print("ПРЕДУПРЕЖДЕНИЕ: не удалось обновить Lightbox.draw")
    elif source != original:
        backup(path)
        path.write_text(source, encoding="utf-8")
        print("Табло больше не будут дублировать напечатанные подписи")


