def patch_main_hints(root: Path) -> None:
    hint_method = '    def _draw_training_hint_overlay(self):\n        """Draw a precise, readable hint anchored to the active target control."""\n        device = self.active_device\n        if not device or not device.hint_service:\n            return\n\n        service = device.hint_service\n        action = service.get_current_action()\n        if action is None:\n            return\n\n        target = device.get_element_by_name(action.parent_element_name)\n        if target is None:\n            return\n\n        # When the action belongs to another physical panel, show a clear\n        # navigation banner instead of highlighting coordinates from the wrong image.\n        if target.page_key != device.current_page_key:\n            page_value = target.page_key.value if hasattr(target.page_key, "value") else str(target.page_key)\n            label = f"Нужный блок: {page_value}  →"\n            font = pygame.font.SysFont("Arial", 20, bold=True)\n            text_surf = font.render(label, True, (255, 220, 120))\n            box_w = min(max(360, text_surf.get_width() + 48), SCREEN_WIDTH - 32)\n            box_h = 48\n            box = pygame.Rect((SCREEN_WIDTH - box_w) // 2, CANVAS_HEIGHT - box_h - 18, box_w, box_h)\n            panel = pygame.Surface(box.size, pygame.SRCALPHA)\n            pygame.draw.rect(panel, (9, 19, 29, 245), panel.get_rect(), border_radius=9)\n            pygame.draw.rect(panel, (0, 190, 220), panel.get_rect(), width=2, border_radius=9)\n            panel.blit(text_surf, ((box_w - text_surf.get_width()) // 2, (box_h - text_surf.get_height()) // 2))\n            self.screen.blit(panel, box.topleft)\n            return\n\n        # native_rect_to_canvas accounts for the background\'s exact fitted scale and x offset.\n        if getattr(device, "use_native_coordinates", False) and hasattr(device, "native_rect_to_canvas"):\n            target_rect = device.native_rect_to_canvas(target.rect)\n        else:\n            target_rect = target.rect.copy()\n\n        if target_rect.width <= 0 or target_rect.height <= 0:\n            return\n\n        target_rect = target_rect.clip(pygame.Rect(0, 0, SCREEN_WIDTH, CANVAS_HEIGHT))\n        if target_rect.width <= 0 or target_rect.height <= 0:\n            return\n\n        # Bright target frame with a subtle outer glow.\n        frame = target_rect.inflate(16, 16)\n        pygame.draw.rect(self.screen, (0, 90, 120), frame.inflate(6, 6), width=5, border_radius=9)\n        pygame.draw.rect(self.screen, (0, 220, 245), frame, width=3, border_radius=8)\n\n        badge_text = service.get_hint_level_badge() or "ПОДСКАЗКА"\n        body_text = service.get_current_hint_text() or action.hint_text or "Выполните указанное действие."\n        mistake_text = getattr(service, "last_mistake_text", "")\n\n        badge_font = pygame.font.SysFont("Arial", 12, bold=True)\n        body_font = pygame.font.SysFont("Arial", 16, bold=True)\n        small_font = pygame.font.SysFont("Arial", 13)\n        max_text_width = min(370, SCREEN_WIDTH - 80)\n\n        def wrap(text, font, max_width):\n            words = str(text).split()\n            lines = []\n            current = ""\n            for word in words:\n                candidate = word if not current else current + " " + word\n                if font.size(candidate)[0] <= max_width:\n                    current = candidate\n                else:\n                    if current:\n                        lines.append(current)\n                    current = word\n            if current:\n                lines.append(current)\n            return lines or [""]\n\n        body_lines = wrap(body_text, body_font, max_text_width)[:4]\n        mistake_lines = wrap(mistake_text, small_font, max_text_width)[:2] if mistake_text else []\n        bubble_w = min(max_text_width + 36, SCREEN_WIDTH - 32)\n        bubble_h = 18 + 18 + 8 + len(body_lines) * 21 + (6 + len(mistake_lines) * 17 if mistake_lines else 0) + 16\n\n        # Put the bubble on the side with more room; clamp it away from the top ribbon and navbar.\n        gap = 22\n        if target_rect.centerx < SCREEN_WIDTH // 2:\n            bubble_x = target_rect.right + gap\n            if bubble_x + bubble_w > SCREEN_WIDTH - 12:\n                bubble_x = target_rect.left - bubble_w - gap\n        else:\n            bubble_x = target_rect.left - bubble_w - gap\n            if bubble_x < 12:\n                bubble_x = target_rect.right + gap\n        bubble_x = max(12, min(SCREEN_WIDTH - bubble_w - 12, bubble_x))\n        bubble_y = target_rect.centery - bubble_h // 2\n        bubble_y = max(44, min(CANVAS_HEIGHT - bubble_h - 12, bubble_y))\n        bubble_rect = pygame.Rect(int(bubble_x), int(bubble_y), int(bubble_w), int(bubble_h))\n\n        # Connector from bubble to the actual target frame.\n        if bubble_rect.left >= frame.right:\n            start = (bubble_rect.left, bubble_rect.centery)\n            end = (frame.right, frame.centery)\n        elif bubble_rect.right <= frame.left:\n            start = (bubble_rect.right, bubble_rect.centery)\n            end = (frame.left, frame.centery)\n        elif bubble_rect.top >= frame.bottom:\n            start = (bubble_rect.centerx, bubble_rect.top)\n            end = (frame.centerx, frame.bottom)\n        else:\n            start = (bubble_rect.centerx, bubble_rect.bottom)\n            end = (frame.centerx, frame.top)\n        pygame.draw.line(self.screen, (0, 220, 245), start, end, 3)\n        pygame.draw.circle(self.screen, (240, 255, 255), end, 4)\n\n        bubble = pygame.Surface(bubble_rect.size, pygame.SRCALPHA)\n        pygame.draw.rect(bubble, (8, 17, 27, 246), bubble.get_rect(), border_radius=10)\n        pygame.draw.rect(bubble, (0, 205, 230, 255), bubble.get_rect(), width=2, border_radius=10)\n        badge_surf = badge_font.render(badge_text, True, (100, 225, 245))\n        bubble.blit(badge_surf, (16, 10))\n        text_y = 34\n        for line in body_lines:\n            line_surf = body_font.render(line, True, (245, 249, 252))\n            bubble.blit(line_surf, (16, text_y))\n            text_y += 21\n        if mistake_lines:\n            text_y += 4\n            for line in mistake_lines:\n                line_surf = small_font.render(line, True, (255, 190, 120))\n                bubble.blit(line_surf, (16, text_y))\n                text_y += 17\n        self.screen.blit(bubble, bubble_rect.topleft)\n'
    path = root / "main.py"
    if not path.exists():
        print("ПРЕДУПРЕЖДЕНИЕ: main.py не найден — исправление подсказок пропущено")
        return
    original = source = path.read_text(encoding="utf-8")
    if "def _draw_training_hint_overlay(self):" in source:
        # Replace a previously installed version so reruns are deterministic.
        method_pattern = re.compile(r"(?ms)^    def _draw_training_hint_overlay\(self\):.*?(?=^    def [A-Za-z_]\w*\(|^class [A-Za-z_]\w*|\Z)")
        source, _ = method_pattern.subn(lambda _m: hint_method.rstrip() + "\n\n", source, count=1)
    else:
        marker = re.search(r"(?m)^    def draw_simulation\(self\):", source)
        if marker:
            source = source[:marker.start()] + hint_method + "\n\n" + source[marker.start():]

    # Replace the complete old overlay region, including the old rect-only adapter.
    region = re.compile(r"(?ms)^        # 3\. Draw Training Hints Overlay\s*\n.*?(?=^        # 4\. Draw Bottom Navbar)")
    replacement = (
        "        # 3. Draw coordinate-correct Training Hints Overlay\n"
        "        if self.mode == ApplicationMode.TRAINING and self.active_device:\n"
        "            self._draw_training_hint_overlay()\n\n"
    )
    source, region_count = region.subn(lambda _m: replacement, source, count=1)
    if region_count == 0:
        old_call = "self.hint_renderer.draw(self.screen, self.active_device)"
        source = source.replace(old_call, "self._draw_training_hint_overlay()")

    if source != original:
        backup(path)
        path.write_text(source, encoding="utf-8")
        print("Подсказки привязаны к фактическим координатам органов управления")
    else:
        print("Подсказки уже обновлены")

def patch_exam_flow(root: Path) -> None:
    path = root / "main.py"
    if not path.exists():
        print("ПРЕДУПРЕЖДЕНИЕ: main.py не найден — исправление экзамена пропущено")
        return
    original = source = path.read_text(encoding="utf-8")

    open_exam = '''    def _open_exam_auth_dialog(self):
        """Open network authentication if it works; don't terminate on setup errors."""
        dialog_cls = globals().get("StudentAuthDialog")
        client = getattr(self, "student_client", None)
        confirm = getattr(self, "_on_auth_confirmed", None)
        if dialog_cls is not None and client is not None and callable(confirm):
            try:
                self.active_dialog = dialog_cls(
                    on_confirm=confirm,
                    on_cancel=lambda: setattr(self, "active_dialog", None),
                    client=client,
                )
                return
            except Exception as exc:
                print(f"Не удалось открыть сетевой вход в экзамен: {exc}")

        # Local/offline exam fallback: the simulation remains available even
        # when an optional auth/network component is missing or unavailable.
        self.mode = ApplicationMode.EXAMINE
        self.is_network_exam = False
        if not getattr(self, "student_data", None):
            self.student_data = {"full_name": "Курсант", "group": "401", "pc_name": "ПК"}
        if hasattr(self, "_open_device_selection"):
            self._open_device_selection(ApplicationMode.EXAMINE)
        else:
            self.active_dialog = None
            print("Не найден экран выбора устройства для автономного экзамена.")
'''
    source, changed_open = replace_method(source, "_open_exam_auth_dialog", open_exam)
    if changed_open:
        print("Исправлен запуск окна экзамена")

    prep = '''    def _prepare_examine_session(self, device: DeviceBase, algo):
        """Try network exam first, then continue locally if the server is unavailable."""
        total_steps = len([action for action in algo.actions if action.use_in_examine_check])
        student_data = getattr(self, "student_data", None) or {
            "full_name": "Курсант", "group": "401", "pc_name": "ПК"
        }
        self.student_data = student_data
        client = getattr(self, "student_client", None)
        logged_in = False

        if client is not None:
            try:
                logged_in = bool(client.login_sync(
                    full_name=student_data.get("full_name", "Курсант"),
                    group=student_data.get("group", "401"),
                    pc_name=student_data.get("pc_name", socket.gethostname() if hasattr(socket, "gethostname") else "ПК"),
                    device_name=device.readable_name,
                    algorithm_name=algo.name,
                    max_time_seconds=600.0,
                    total_steps=total_steps,
                ))
            except Exception as exc:
                print(f"Сервер экзамена недоступен; запускаю автономный экзамен: {exc}")
                logged_in = False

        if not logged_in:
            self.is_network_exam = False
            self.start_simulation(device, algo)
            return

        self.is_network_exam = True
        try:
            client.start()
            if getattr(client, "is_exam_started_by_server", False):
                self.start_simulation(device, algo)
                return

            def on_start_offline():
                self.active_dialog = None
                self.start_simulation(device, algo)

            def on_cancel_wait():
                self.active_dialog = None
                try:
                    client.stop()
                except Exception:
                    pass
                self.state = AppState.MAIN_MENU

            waiting_cls = globals().get("WaitingForTeacherDialog")
            if waiting_cls is None:
                self.is_network_exam = False
                self.start_simulation(device, algo)
                return
            self.active_dialog = waiting_cls(
                self.student_data,
                device.readable_name,
                algo.name,
                on_start_now=on_start_offline,
                on_cancel=on_cancel_wait,
            )
            self._pending_device = device
            self._pending_algo = algo

            def handle_cmd(cmd_type, payload):
                client.incoming_commands.put((cmd_type, payload))

            client.on_command_callback = handle_cmd
        except Exception as exc:
            print(f"Не удалось подключиться к экзамену; продолжаю автономно: {exc}")
            try:
                client.stop()
            except Exception:
                pass
            self.is_network_exam = False
            self.active_dialog = None
            self.start_simulation(device, algo)
'''
    source, changed_prep = replace_method(source, "_prepare_examine_session", prep)
    if changed_prep:
        print("Добавлен автономный резервный путь при сбое экзамена/сервера")

    if source != original:
        backup(path)
        path.write_text(source, encoding="utf-8")


def syntax_check(root: Path) -> bool:
    files = [root / "devices" / "device_base.py", root / "devices" / "smalta.py",
             root / "controls" / "thumbler.py", root / "controls" / "big_button.py",
             root / "controls" / "lightbox.py", root / "controls" / "gauge_arrow.py",
             root / "main.py"]
    good = True
    for path in files:
        if not path.exists():
            continue
        try:
            ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        except SyntaxError as exc:
            print(f"ОШИБКА синтаксиса в {path.relative_to(root)}: {exc}")
            good = False
    if good:
        print("Проверка синтаксиса Python пройдена")
    return good


def main() -> int:
    try:
        root = locate_root()
    except FileNotFoundError as exc:
        print(f"ОШИБКА: {exc}")
        return 2

    if not (root / "devices" / "smalta.py").is_file():
        print("ОШИБКА: не найдена devices/smalta.py — это не папка проекта SmaltaSimPygame")
        return 2

    print(f"Проект: {root}")
    write_payloads(root)
    mirror_frozen_assets(root)
    patch_device_base(root)
    patch_smalta_coordinates(root)
    patch_lightbox(root)
    patch_gauge_arrows(root)
    patch_main_hints(root)
    patch_exam_flow(root)
    if not syntax_check(root):
        print("ПРОВЕРКА НЕ ПРОЙДЕНА. Резервные копии сохранены; посмотри ошибку выше.")
        return 3
    print("\nГотово. Запусти исходный проект командой: python main.py")
    print("Если запускаешь .exe, его надо пересобрать: эта установка меняет исходники Python.")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
